 function isMobile(){return matchMedia('(max-width:700px)').matches||'ontouchstart'in window}
 function updateInventory(){const names={wood:'Planks',scrap:'Scrap',cloth:'Cloth',parts:'Parts',ammo:'Ammo',food:'Food',chem:'Chem',fuel:'Fuel'};$('items').innerHTML=Object.entries(resources).map(([k,v])=>`<div class="item"><span>${names[k]}</span><span>${v}</span></div>`).join('')}
