import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const runtime = '/home/runner/.local/share/omgithub-playwright'
const require = createRequire(`${runtime}/package.json`)
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
for (const viewport of [{width:1440,height:900},{width:390,height:844}]) {
  const page = await browser.newPage({viewport})
  const errors=[]
  page.on('pageerror', e=>errors.push(e.message))
  await page.goto('http://localhost:3002')
  await page.locator('#start').click()
  await page.locator('[data-close]').first().click()
  await page.waitForTimeout(500)
  const start = await page.evaluate(()=>({canvas:[document.querySelector('#view').width,document.querySelector('#view').height],prompt:document.querySelector('#prompt').className,clock:document.querySelector('#clock').textContent,modal:document.querySelector('#helpModal').className,body:document.body.scrollHeight}))
  await page.screenshot({path:`/tmp/opencode/started-${viewport.width}.png`})
  console.log(JSON.stringify({viewport,start,errors}))
  await page.close()
}
await browser.close()

